"""
TASK 2 - Find "People You May Know".

Input:
    outputs/clean_social_data.json

Output:
    outputs/people_you_may_know.csv

Logic:
    Friends of your friends may be people you know.
    Count how many mutual friends each candidate shares with you.
"""

import json
from pathlib import Path
from collections import Counter

import pandas as pd

BASE_DIR = Path(__file__).resolve().parent
INPUT_FILE = BASE_DIR / "outputs" / "clean_social_data.json"
OUTPUT_DIR = BASE_DIR / "outputs"
OUTPUT_DIR.mkdir(exist_ok=True)

# Load the cleaned network generated by Task 1.
with INPUT_FILE.open(encoding="utf-8") as file:
    data = json.load(file)

# Convert lists from JSON back into sets for quick membership checks.
users = {
    user["id"]: user
    for user in data["users"]
}

friends_of = {
    user_id: set(user["friends"])
    for user_id, user in users.items()
}

name_of = {
    user_id: user["name"]
    for user_id, user in users.items()
}


def people_you_may_know(user_id, top_n=5):
    """
    Return suggested users and their mutual-friend counts.

    Steps:
    1. Visit every direct friend of the selected user.
    2. Visit each direct friend's friends.
    3. Skip the selected user and existing friends.
    4. Count how often each candidate appears.
    5. Return the highest-scoring candidates.
    """
    mutual_counts = Counter()

    # Look at friends of each of the selected user's friends.
    for friend_id in friends_of[user_id]:
        for friend_of_friend in friends_of[friend_id]:

            # Do not suggest yourself or someone already in your friend list.
            if friend_of_friend == user_id:
                continue

            if friend_of_friend in friends_of[user_id]:
                continue

            # Each appearance represents one mutual friend.
            mutual_counts[friend_of_friend] += 1

    return mutual_counts.most_common(top_n)


def mutual_friends(user_a, user_b):
    """Return the names of people who are friends with both users."""
    common_ids = friends_of[user_a] & friends_of[user_b]
    return sorted(name_of[user_id] for user_id in common_ids)


# ---------------------------------------------------------
# Example: show recommendations for Amit (user ID 1)
# ---------------------------------------------------------
selected_user = 1

if selected_user not in users:
    raise ValueError(f"User ID {selected_user} does not exist in cleaned data.")

print(f"People {name_of[selected_user]} may know:")

suggestions = people_you_may_know(selected_user)

for suggested_id, count in suggestions:
    print(f"  {name_of[suggested_id]:<15} - {count} mutual friend(s)")

print("\nMutual-friend details:")
for suggested_id, _ in people_you_may_know(selected_user, top_n=3):
    print(
        f"{name_of[selected_user]} & {name_of[suggested_id]}:",
        mutual_friends(selected_user, suggested_id),
    )

# ---------------------------------------------------------
# Generate the top three suggestions for every user
# ---------------------------------------------------------
recommendation_rows = []

for user_id in sorted(friends_of):
    top_suggestions = people_you_may_know(user_id, top_n=3)

    # Include both the suggested name and mutual-friend score.
    suggestion_text = ", ".join(
        f"{name_of[suggested_id]} ({score})"
        for suggested_id, score in top_suggestions
    )

    recommendation_rows.append({
        "user_id": user_id,
        "user": name_of[user_id],
        "people_you_may_know": suggestion_text or "—",
    })

recommendations_df = pd.DataFrame(recommendation_rows)

# Save one row per user.
output_file = OUTPUT_DIR / "people_you_may_know.csv"
recommendations_df.to_csv(output_file, index=False)

print("\nRecommendations for all users:")
print(recommendations_df.head(10))
print(f"\nSaved: {output_file}")
